package com.progressly.activity.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="habits") public class Habit { public enum Frequency{DAILY,WEEKLY,CUSTOM} @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID userId; @Column(nullable=false,length=180) String name; @Column(length=2000) String description; @Enumerated(EnumType.STRING) @Column(nullable=false) Frequency frequency; @Column(precision=19,scale=4) BigDecimal targetValue; @Column(nullable=false) boolean active; @Column(nullable=false,updatable=false) Instant createdAt; protected Habit(){} public Habit(UUID u,String n,String d,Frequency f,BigDecimal target){userId=u;name=n;description=d;frequency=f==null?Frequency.DAILY:f;targetValue=target;active=true;} @PrePersist void create(){createdAt=Instant.now();} public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getName(){return name;} public String getDescription(){return description;} public Frequency getFrequency(){return frequency;} public BigDecimal getTargetValue(){return targetValue;} public boolean isActive(){return active;} public Instant getCreatedAt(){return createdAt;} public void update(String n,String d,Frequency f,BigDecimal target){name=n;description=d;frequency=f;targetValue=target;} public void active(boolean value){active=value;} }
